import {SCENARIOS,PLAYERS,position,clock,story} from './engine.js';
import {matchCenterSnapshot,truthReport} from './analysis-model.js';
import {PRESENTER_PROFILES as profiles} from './presenter-profiles.js';
const $=id=>document.getElementById(id),el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;};
const svg=(tag,attrs)=>{const n=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const [k,v]of Object.entries(attrs))n.setAttribute(k,String(v));return n;};
let scenario=SCENARIOS[0],time=18,selectedPlayer=7,corrected=false,playing=false,lastFrame=0,lastDraw=0,section='watch';
const emit=(name,detail)=>document.dispatchEvent(new CustomEvent(name,{detail}));
function stop(){playing=false;for(const b of document.querySelectorAll('.scenario-play'))b.textContent='▶ Play sequence';}
function navigate(name){for(const node of document.querySelectorAll('.extension-view'))node.hidden=node.id!==name;for(const node of document.querySelectorAll('.masthead .nav')){const active=node.dataset.section===name;node.classList.toggle('selected',active);node.setAttribute('aria-pressed',String(active));}emit('btr-section',name);if(name==='presenters')emit('btr-request-contributions');}
for(const button of document.querySelectorAll('[data-section]'))button.addEventListener('click',()=>navigate(button.dataset.section));
document.addEventListener('btr-section',e=>{section=e.detail;if(!['centre','truth','inside'].includes(section))stop();render();});
document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});
for(const select of document.querySelectorAll('.scenario-select'))select.addEventListener('change',()=>{scenario=SCENARIOS.find(s=>s.id===select.value);time=0;corrected=false;stop();render();});
for(const slider of document.querySelectorAll('.scenario-time'))slider.addEventListener('input',()=>{stop();time=Number(slider.value);render();});
function tick(now){if(!playing)return;if(lastFrame)time=Math.min(36,time+(now-lastFrame)/1000);lastFrame=now;if(now-lastDraw>80||time===36){render();lastDraw=now;}if(time===36)stop();else requestAnimationFrame(tick);}
for(const b of document.querySelectorAll('.scenario-play'))b.addEventListener('click',()=>{if(playing){stop();return;}if(time>=36)time=0;playing=true;lastFrame=0;for(const button of document.querySelectorAll('.scenario-play'))button.textContent='Ⅱ Pause sequence';requestAnimationFrame(tick);});
const rosterRows=new Map();
for(const p of PLAYERS){const button=el('button','lineup-row'),number=el('span','shirt-number',String(p.number||p.id)),name=el('span','lineup-name',p.name),stat=el('span','lineup-stat');button.append(number,name,stat);button.setAttribute('aria-label',`Follow ${p.name}`);button.addEventListener('click',()=>{selectedPlayer=p.id;render();});$(p.team==='harbor'?'home-lineup':'away-lineup').append(button);rosterRows.set(p.id,{button,stat});}
function dot(parent,x,y,color,r=1.8){parent.append(svg('circle',{cx:x,cy:y,r,fill:color,stroke:'#fff8','stroke-width':.25}));}
function renderCenter(state){
 const data=$('formation-pitch').querySelector('.pitch-data');data.replaceChildren();
 for(const p of state.players){const [x,y]=p.position,color=p.team==='harbor'?'#c8ed48':'#77b3ff';if(p.id===selectedPlayer)data.append(svg('circle',{cx:x,cy:y,r:3.3,fill:'none',stroke:'white','stroke-width':.4}));dot(data,x,y,color);const number=svg('text',{x,y:y+.65,'text-anchor':'middle','font-size':1.7,'font-weight':700,fill:'#102136'});number.textContent=p.number;data.append(number);const row=rosterRows.get(p.id);row.stat.textContent=`${p.passes} P · ${p.displacement.toFixed(1)} m`;row.button.classList.toggle('selected',p.id===selectedPlayer);row.button.setAttribute('aria-pressed',String(p.id===selectedPlayer));}
 const p=state.players.find(p=>p.id===selectedPlayer);$('player-detail').replaceChildren(el('span','micro','PLAYER FOCUS'),el('h3','',p.name));const stats=el('div','player-stats');for(const [value,label]of [[`${p.completed}/${p.passes}`,'PASSES COMPLETED'],[p.involvements,'EVENT INVOLVEMENTS'],[p.displacement.toFixed(1)+' m','STRAIGHT-LINE DISPLACEMENT']]){const item=el('div');item.append(el('strong','',String(value)),el('span','',label));stats.append(item);}$('player-detail').append(stats);
 const network=$('network-pitch').querySelector('.pitch-data'),team=$('network-team').value;network.replaceChildren();const passes=state.seen.filter(e=>e.type==='pass'&&e.team===team&&e.outcome==='complete');for(const e of passes){network.append(svg('line',{x1:e.start[0],y1:e.start[1],x2:e.endPosition[0],y2:e.endPosition[1],stroke:team==='harbor'?'#c8ed48':'#77b3ff','stroke-width':.7,opacity:.8}));dot(network,...e.start,'#d7ecff',1);dot(network,...e.endPosition,team==='harbor'?'#c8ed48':'#77b3ff',1.5);}$('network-note').textContent=`${passes.length} completed passes shown. Links use each pass’s recorded origin and destination; unfinished events stay out.`;
 const shots=$('shots-pitch').querySelector('.pitch-data');shots.replaceChildren();const attempts=state.seen.filter(e=>e.type==='shot');for(const e of attempts){dot(shots,...e.start,e.outcome==='goal'?'#c8ed48':'#ffa888',2.4);shots.append(svg('line',{x1:e.start[0],y1:e.start[1],x2:e.endPosition[0],y2:e.endPosition[1],stroke:'#fff8','stroke-width':.4,'stroke-dasharray':'1 1'}));}$('shots-note').textContent=attempts.length?attempts.map(e=>`${e.outcome==='goal'?'Goal':e.outcome==='saved'?'Saved':'Shot'} · ${clock(scenario,e.end)}`).join(' · '):'No completed shot at this point in the sequence. No xG estimate is assigned.';
 const heat=$('density-pitch').querySelector('.pitch-data');heat.replaceChildren();const bins=new Map();for(const e of state.seen){for(const loc of [e.start,...(e.type==='pass'?[e.endPosition]:[])]){const x=Math.min(90,Math.floor(loc[0]/15)*15),y=Math.min(51,Math.floor(loc[1]/17)*17),key=x+','+y;bins.set(key,(bins.get(key)||0)+1);}}const max=Math.max(1,...bins.values());for(const [key,count]of bins){const [x,y]=key.split(',').map(Number);heat.append(svg('rect',{x,y,width:15,height:17,fill:'#d5ed57',opacity:.15+.6*count/max}));}
}
function renderTruth(){const audit=truthReport(scenario,time,corrected),m=audit.reading.metrics,c=audit.reference.metrics;$('reveal-truth').disabled=!audit.correctionAvailable;$('reveal-truth').setAttribute('aria-pressed',String(audit.revealed));$('reveal-truth').textContent=!audit.correctionAvailable?'Choose “The unseen run”':audit.revealed?'Restore original tracking ↺':'Apply tracking correction ↗';$('truth-version').textContent=audit.revealed?'CORRECTED TRACKING · R2':'ORIGINAL TRACKING · R1';$('audit-supported').textContent=`${audit.supported}/${audit.checked}`;$('audit-withdrawn').textContent=String(audit.withdrawn);$('audit-cutoff').textContent=time.toFixed(1)+'s';$('original-meter').value=m.lateral;$('current-meter').value=c.lateral;$('original-reading').textContent=m.lateral.toFixed(1)+' m';$('current-reading').textContent=c.lateral.toFixed(1)+' m';const n=story(scenario,time,'analyst','en',corrected,selectedPlayer);$('truth-headline').textContent=n.title;$('truth-copy').textContent=n.body;$('claim-rows').replaceChildren();for(const row of audit.rows){const tr=el('tr');tr.append(el('td','',row.claim),el('td','',row.reading),el('td','',row.reference),el('td','audit-'+row.status,row.status==='supported'?'Supported':row.status==='withdrawn'?'Withdrawn':'Pending'));$('claim-rows').append(tr);}
 const chart=$('truth-trace');chart.replaceChildren();for(const y of [0,10,20,30]){const yp=175-y*4.5;chart.append(svg('line',{x1:34,y1:yp,x2:580,y2:yp,stroke:'#31415a','stroke-width':1}));const label=svg('text',{x:4,y:yp+4,fill:'#91a6c3','font-size':10});label.textContent=y+'m';chart.append(label);}for(const t of [0,9,18,27,36]){const label=svg('text',{x:34+t/36*546,y:199,fill:'#91a6c3','font-size':10,'text-anchor':'middle'});label.textContent=t+'s';chart.append(label);}for(const [correct,color]of [[false,'#7bb8ff'],[corrected,'#d1fa38']]){const points=[];for(let t=0;t<=time;t+=.25)points.push(`${34+t/36*546},${175-Math.abs(position(scenario,102,t,correct)[1]-position(scenario,102,0,correct)[1])*4.5}`);if(points.length)chart.append(svg('polyline',{points:points.join(' '),fill:'none',stroke:color,'stroke-width':correct?3:2,...(!correct?{'stroke-dasharray':'4 3'}:{})}));}const cursor=34+time/36*546;chart.append(svg('line',{x1:cursor,y1:18,x2:cursor,y2:177,stroke:'#dde8ff','stroke-width':1,'stroke-dasharray':'2 4'}));
}
function render(){const state=matchCenterSnapshot(scenario,time,corrected);for(const s of document.querySelectorAll('.scenario-select'))s.value=scenario.id;for(const s of document.querySelectorAll('.scenario-time'))s.value=time;for(const c of document.querySelectorAll('.scenario-clock'))c.textContent=clock(scenario,time);if(section==='centre')renderCenter(state);if(section==='truth')renderTruth();emit('btr-analysis-state',{scenario:scenario.id,time,corrected,focus:selectedPlayer,section});}
$('network-team').addEventListener('change',render);$('reveal-truth').addEventListener('click',()=>{corrected=!corrected;render();});
$('export-audit').addEventListener('click',()=>{const audit=truthReport(scenario,time,corrected),data={schema:'btr.tracking-audit.v1',synthetic:true,scenario:scenario.id,sequence_second:time,revision:corrected?2:1,correction:corrected?'Defender 102 held at original coordinates':null,checks:audit.rows,evidence: audit.reading.seen,limits:['Deterministic checks of authored synthetic data.','No AI prose accuracy score or causal proof.','Not derived from the featured film.']},url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=el('a');a.href=url;a.download=`btr-audit-${scenario.id}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
const profileLines=new Map();
for(const p of profiles){
 const card=el('article','presenter-card '+p.id),art=el('div','presenter-art'),portrait=el('img','presenter-photo');
 portrait.src='assets/'+p.image+'-portrait.webp';portrait.alt=p.name+', a fictional AI football presenter';portrait.loading='lazy';art.append(portrait,el('span','persona-tag','FICTIONAL AI PRESENTER'));
 const body=el('div','presenter-body');body.append(el('span','eyebrow',p.role),el('h2','',p.name.toUpperCase()),el('h3','',p.title),el('p','presenter-voice',p.voice));
 const expertise=el('div','expertise-tags');for(const tag of p.expertise)expertise.append(el('span','',tag));body.append(expertise,el('p','',p.body));
 const source=el('div','presenter-source');source.append(el('span','latest-label','WORKING EVIDENCE'),el('p','',p.tools));body.append(source);
 const method=el('details','presenter-method');method.append(el('summary','','Method, handoff & limits'));const steps=el('ol');for(const step of p.method)steps.append(el('li','',step));method.append(steps,el('span','latest-label','PASSING THE MIC'),el('p','',p.handoff),el('span','latest-label','EVIDENCE LIMIT'),el('p','',p.boundary));body.append(method);
 const example=el('button','presenter-question');example.append(el('span','latest-label','TRY A QUESTION ↗'),el('span','',p.question));example.addEventListener('click',()=>emit('btr-agent-question',{role:p.id,question:p.question}));body.append(example);
 const latest=el('blockquote','','Watch the film to see this role’s latest public contribution.'),button=el('button','join-presenter','Join '+p.name+' in the room ↗');button.addEventListener('click',()=>emit('btr-profile-role',p.id));body.append(el('span','latest-label','LATEST CONTRIBUTION'),latest,button);card.append(art,body);$('presenter-grid').append(card);profileLines.set(p.id,latest);
}
document.addEventListener('btr-contributions',e=>{for(const p of profiles){const post=e.detail.posts.find(x=>x.role===p.id);profileLines.get(p.id).textContent=post?`${post.engine==='azure_openai'?'AI':'Reviewed fallback'} · ${post.summary}`:'Watch the film to see this role’s latest public contribution.';}});
$('return-room').addEventListener('click',()=>emit('btr-profile-role',null));

document.addEventListener("btr-analysis-request",()=>render());
document.addEventListener("btr-seek-scenario",e=>{const s=SCENARIOS.find(s=>s.id===e.detail.scenario);if(s){if(s!==scenario)corrected=false;scenario=s;time=Math.max(0,Math.min(s.duration,Number(e.detail.time)||0));stop();render();}});
